CREATE TABLE pilotage_diagnostics.requests (id TEXT PRIMARY KEY CHECK (id ~ '^[0-9a-f]{32}$'), incident_id BIGINT NOT NULL REFERENCES pilotage_incidents.incidents(id), actor_id BIGINT NOT NULL REFERENCES pilotage_auth.users(id), client_key TEXT NOT NULL CHECK (client_key ~ '^[0-9a-f]{32}$'), reason TEXT NOT NULL CHECK (char_length(btrim(reason)) BETWEEN 15 AND 500), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','completed','blocked','failed','interrupted')), created_at DOUBLE PRECISION NOT NULL, claimed_at DOUBLE PRECISION, finished_at DOUBLE PRECISION, result_run_id TEXT CHECK (result_run_id IS NULL OR result_run_id ~ '^[0-9a-f]{32}$'), UNIQUE(actor_id,client_key));
CREATE UNIQUE INDEX diagnostic_requests_active_incident ON pilotage_diagnostics.requests(incident_id) WHERE status IN ('pending','running');
CREATE INDEX diagnostic_requests_recent ON pilotage_diagnostics.requests(created_at DESC,id DESC);
